#include <stdio.h>
#include <math.h>

/* Pinhole camera, Lambertian sphere, and a checkerboard plane. */
int main(void) {
    const int w=2400,h=1800;
    FILE *f=fopen("reconstructed.ppm","wb");
    if(!f) return 1;
    fprintf(f,"P6\n%d %d\n255\n",w,h);
    for(int y=0;y<h;y++) for(int x=0;x<w;x++) {
        float dx=(2.0f*x/(w-1)-1)*w/h;
        float dy=1-2.0f*y/(h-1);
        float a=dx*dx+dy*dy+1, b=.5f*dy-5;
        float d=b*b-24.25f*a;
        float r,g,bl;
        if(d>=0) {
            float t=(-b-sqrtf(d))/a;
            float nx=t*dx,ny=.5f+t*dy,nz=5-t;
            r=.2f+.8f*fmaxf(0,(nx+ny-nz)/sqrtf(3));
            g=bl=.2f*r;
        } else if(dy<0) {
            float t=-1.5f/dy, px=t*dx,pz=5-t;
            float v=(((int)floorf(px)+(int)floorf(pz))&1)?.9f:.4f;
            float q=(px-.999f-pz)/sqrtf(3);
            int shadow=q<0 && q*q>px*px+pz*pz+.999f*.999f-1;
            r=g=bl=v*(shadow?.2f:(.2f+.8f/sqrtf(3)));
        } else {
            float t=.5f*(dy/sqrtf(a)+1);
            r=(1-t)+.5f*t; g=(1-t)+.7f*t; bl=1;
        }
        unsigned char rgb[3]={(int)(255.99f*r),(int)(255.99f*g),(int)(255.99f*bl)};
        fwrite(rgb,1,3,f);
    }
    return fclose(f)!=0;
}
